use rig::prelude::*;
use serde::{Deserialize, Serialize};
use rig::providers::openai::{self, OpenAI};


#[derive(Embed, Clone, Serialize, Deserialize, Debug)]
struct WordDefinition {
    id: String,
    #[embed]
    definition: String,
}


#[tokio::main]
async fn main() -> Result<(), anyhow::Error> {
    let model = OpenAI::from_env()?.embedding(openai::TEXT_EMBEDDING_3_SMALL, None);


    let documents = vec![
        WordDefinition { id: "doc0".into(), definition: "First document content".into() },
        WordDefinition { id: "doc1".into(), definition: "Second document content".into() },
    ];


    let embeddings = EmbeddingsBuilder::new(model.clone())
        .documents(documents)?
        .build()
        .await?;


    // Build the store, then an index that embeds queries with the same model.
    let index = InMemoryVectorStore::from_documents(embeddings).index(model);


    let req = VectorSearchRequest::builder()
        .query("search query")
        .samples(5)
        .build();


    for result in index.top_n::<WordDefinition>(req).await? {
        println!("{:.3} {} {:?}", result.score, result.id, result.document);
    }


    Ok(())
}

use rig::embeddings::Embedding;


#[derive(Serialize, Clone)]
struct WordDefinition { id: String }


let doc = |id: &str| (WordDefinition { id: id.into() }, vec![Embedding::default()]);


// 1. Generated ids: "doc0", "doc1", ...
let store = InMemoryVectorStore::from_documents(vec![doc("a"), doc("b")]);


// 2. Explicit ids
let store = InMemoryVectorStore::from_documents_with_ids(vec![
    ("custom_id_1", doc("a").0, doc("a").1),
    ("custom_id_2", doc("b").0, doc("b").1),
]);


// 3. Ids derived from each document
let store = InMemoryVectorStore::from_documents_with_id_f(
    vec![doc("a"), doc("b")],
    |d| format!("word:{}", d.id),
);

use rig::embeddings::Embedding;
use rig::vector_store::IndexStrategy;


let store = InMemoryVectorStore::builder()
    .index_strategy(IndexStrategy::LSH { num_tables: 8, num_hyperplanes: 16 })
    .documents(embeddings)
    .build();

use rig::vector_store::request::{Filter, SearchFilter};


let req = VectorSearchRequest::builder()
    .query("search query")
    .samples(5)
    .filter(Filter::eq("category", json!("science")))
    .build();

use rig::prelude::*;
use rig::providers::openai::{self, OpenAI};


let client = OpenAI::from_env()?;
let model = client.embedding(openai::TEXT_EMBEDDING_3_SMALL, None);
let index = InMemoryVectorStore::<String>::default().index(model);


let agent = AgentBuilder::new(client.completion(openai::GPT_5_5))
    .preamble("Answer using the retrieved documents.")
    .dynamic_context(2, index)
    .build();
